{
  "id": 72,
  "knowledge": "Premature Resolution Block",
  "description": "A business rule preventing an enforcement action from being marked as 'Resolved' if associated risk metrics (like III) exceed a predefined threshold, ensuring high-risk cases receive sufficient review.",
  "definition": "Block UPDATE of enforcementactions.resstat to 'Resolved' IF linked investigationdetails yield an Investigation Intensity Index > 75"
}

{
  "id": 6,
  "knowledge": "Investigation Intensity Index (III)",
  "description": "Combines behavioral and network analysis scores from an investigation.",
  "definition": "III = (0.6 \\times \\text{behansc}) + (0.4 \\times \\text{netansc})"
}

args.sql:
CREATE OR REPLACE FUNCTION check_enforcement_resolution()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.resstat = 'Resolved' AND EXISTS (
        SELECT 1
        FROM investigationdetails AS i
        JOIN compliancecase AS c ON i.compref = c.compreg
        WHERE c.compreg = NEW.compref2
          AND (0.6 * i.behansc + 0.4 * i.netansc) > 75
    ) THEN
        RAISE EXCEPTION 'Premature Resolution Block: investigation intensity exceeds 75 for compliance case %', NEW.compref2;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER enforcement_resolution_check
BEFORE UPDATE ON enforcementactions
FOR EACH ROW
EXECUTE FUNCTION check_enforcement_resolution();

